UPDATE stock
SET quantity = quantity - #{quantity}
WHERE id = #{id} AND deleted = 0 AND quantity >= #{quantity}

UPDATE stock
SET quantity = quantity + #{quantity}
WHERE id = #{id} AND deleted = 0

UPDATE stock
SET locked_qty = locked_qty + #{quantity}, quantity = quantity - #{quantity}
WHERE id = #{id} AND deleted = 0 AND quantity >= #{quantity}

UPDATE stock
SET locked_qty = locked_qty - #{quantity}, quantity = quantity + #{quantity}
WHERE id = #{id} AND deleted = 0 AND locked_qty >= #{quantity}
